CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_migrations VALUES (1);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(key TEXT NOT NULL, at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS login_attempts_window ON login_attempts(key,at);
CREATE TABLE IF NOT EXISTS walks(id TEXT PRIMARY KEY,owner TEXT NOT NULL,preferences TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',heartbeat INTEGER NOT NULL,created INTEGER NOT NULL,run_count INTEGER NOT NULL DEFAULT 0,last_run INTEGER NOT NULL DEFAULT 0,last_lat REAL,last_lng REAL,thread_id TEXT,message TEXT,pending_preferences INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,walk_id TEXT NOT NULL REFERENCES walks(id),state TEXT NOT NULL,location TEXT NOT NULL,created INTEGER NOT NULL,started INTEGER,finished INTEGER,lease TEXT,tool_count INTEGER NOT NULL DEFAULT 0,research_count INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS one_running_job ON jobs(state) WHERE state='running';
CREATE TABLE IF NOT EXISTS profiles(id TEXT PRIMARY KEY,data TEXT NOT NULL,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS candidate_refs(walk_id TEXT NOT NULL,id TEXT NOT NULL,PRIMARY KEY(walk_id,id));
CREATE TABLE IF NOT EXISTS encounters(walk_id TEXT NOT NULL,id TEXT NOT NULL,first_seen INTEGER NOT NULL,last_seen INTEGER NOT NULL,PRIMARY KEY(walk_id,id));
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,walk_id TEXT NOT NULL,type TEXT NOT NULL,data TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS counters(day TEXT NOT NULL,kind TEXT NOT NULL,value INTEGER NOT NULL,PRIMARY KEY(day,kind));
CREATE TABLE IF NOT EXISTS research_requests(job_id TEXT NOT NULL,company_id TEXT NOT NULL,count INTEGER NOT NULL,PRIMARY KEY(job_id,company_id));
